                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue

                # Extend from beyond both ends of the adjacent matching pair.
                for rr, cc, sr, sc in (
                    (r - dr, c - dc, -dr, -dc),
                    (nr + dr, nc + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 7:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
